import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long MOD = (long) 1e9 + 7;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        long result_power;
        if (k == 0) {
            result_power = n - 1;
        } else if (k == 1) {
            result_power = n;
        } else {
            int cycle_length = 1;
            long val = k;
            while (val != 1) {
                val = (val * k) % n;
                cycle_length++;
            }
            result_power = (n - 1) / cycle_length;
        }
        System.out.println(powMod(n, result_power, MOD));
        sc.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        long curr = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * curr) % mod;
            }
            curr = (curr * curr) % mod;
            exp >>= 1;
        }
        return result;
    }
}
